// ── Component Interface (base class in JS) ────────────────────────
class FileSystemItem {
  getName()        { throw new Error('getName() not implemented'); }
  getSize()        { throw new Error('getSize() not implemented'); }
  print(indent = '') { throw new Error('print() not implemented'); }
}

// ── Leaf: knows its own size, has no children ─────────────────────
class File extends FileSystemItem {
  constructor(name, sizeKB) {
    super();
    this._name = name;
    this._size = sizeKB;
  }
  getName()          { return this._name; }
  getSize()          { return this._size; }
  print(indent = '') { console.log(`${indent}📄 ${this._name} (${this._size} KB)`); }
}

// ── Composite: aggregates children, delegates recursively ─────────
class Folder extends FileSystemItem {
  constructor(name) {
    super();
    this._name     = name;
    this._children = [];
  }
  add(item)    { this._children.push(item); return this; } // fluent
  remove(item) { this._children = this._children.filter(c => c !== item); }

  getName() { return this._name; }
  // Composite magic: delegates to all children
  getSize()  { return this._children.reduce((sum, c) => sum + c.getSize(), 0); }
  print(indent = '') {
    console.log(`${indent}📁 ${this._name}/ (${this.getSize()} KB)`);
    this._children.forEach(c => c.print(indent + '  '));
  }
}

// ── Build the tree ────────────────────────────────────────────────
const root = new Folder('root')
  .add(new Folder('docs')
    .add(new File('guide.pdf', 150))
    .add(new File('notes.txt', 5)))
  .add(new Folder('src')
    .add(new File('index.js', 12))
    .add(new File('utils.js', 8)))
  .add(new File('README.md', 2));

// ── Client treats everything the same ────────────────────────────
root.print();
// 📁 root/ (177 KB)
//   📁 docs/ (155 KB)
//     📄 guide.pdf (150 KB)
//     📄 notes.txt (5 KB)
//   📁 src/ (20 KB)
//     📄 index.js (12 KB)
//     📄 utils.js (8 KB)
//   📄 README.md (2 KB)

console.log(`Total: ${root.getSize()} KB`); // 177 KB

// ── UI tree example: price of a rendered component tree ───────────
class Button {
  constructor(label, renderMs) { this.label = label; this.renderMs = renderMs; }
  getRenderTime() { return this.renderMs; }
  describe()      { return `Button[${this.label}]`; }
}

class Panel {
  constructor(name) { this.name = name; this._children = []; }
  add(c) { this._children.push(c); return this; }
  getRenderTime() { return this._children.reduce((s, c) => s + c.getRenderTime(), 0); }
  describe()      { return `Panel[${this.name}] children=${this._children.length}`; }
}

const ui = new Panel('App')
  .add(new Button('Submit', 2))
  .add(new Panel('Sidebar').add(new Button('Menu', 1)).add(new Button('Close', 1)))
  .add(new Button('Cancel', 2));

console.log(`UI render time: ${ui.getRenderTime()} ms`); // 6 ms

// ── Pure structural skeleton ─────────────────────────────────────

// 1. Component Interface
class Component {
  operation() { throw new Error('Not implemented'); }
}

// 2. Leaf — no children, concrete behaviour
class Leaf extends Component {
  constructor(name) { super(); this.name = name; }
  operation() { return `Leaf(${this.name})`; }
}

// 3. Composite — stores and delegates to children
class Composite extends Component {
  constructor(name) {
    super();
    this.name = name;
    this._children = [];
  }
  add(component)    { this._children.push(component); }
  remove(component) { this._children = this._children.filter(c => c !== component); }
  operation() {
    const childResults = this._children.map(c => c.operation()).join(', ');
    return `Composite(${this.name})[${childResults}]`;
  }
}

// 4. Client — uses Component interface only
function clientCode(component) {
  console.log(component.operation());
}

const leaf1 = new Leaf('A');
const leaf2 = new Leaf('B');
const leaf3 = new Leaf('C');

const branch = new Composite('Branch');
branch.add(leaf1);
branch.add(leaf2);

const root = new Composite('Root');
root.add(branch);
root.add(leaf3);

clientCode(root);
// Composite(Root)[Composite(Branch)[Leaf(A), Leaf(B)], Leaf(C)]
